import type { AgentLabel } from './logger.js'
import type { QuestEvent } from './events.js'

/** Per-token pricing in USD (per 1M tokens) */
export interface ModelPricing {
  /** Input tokens price per 1M tokens in USD */
  inputPer1M: number
  /** Output tokens price per 1M tokens in USD */
  outputPer1M: number
  /** Cache read tokens price per 1M tokens in USD */
  cacheReadPer1M: number
}

/** Default model pricing table — can be overridden */
export const DEFAULT_MODEL_PRICING: Record<string, ModelPricing> = {
  'claude-opus-4-5': {
    inputPer1M: 15.0,
    outputPer1M: 75.0,
    cacheReadPer1M: 1.5,
  },
  'claude-sonnet-4-6': {
    inputPer1M: 3.0,
    outputPer1M: 15.0,
    cacheReadPer1M: 0.3,
  },
  'claude-haiku-4-5': {
    inputPer1M: 0.8,
    outputPer1M: 4.0,
    cacheReadPer1M: 0.08,
  },
  // Fallback for unknown models — use Sonnet pricing
  'default': {
    inputPer1M: 3.0,
    outputPer1M: 15.0,
    cacheReadPer1M: 0.3,
  },
}

